Here's a TypeScript React hook (`useDomains`) for a Next.js client component that fetches data from a `/domains` endpoint using a Bearer token. It includes loading and error states, and returns an object with `domains`, `loading`, and `error`.

```tsx
import { useState, useEffect } from 'react';

interface Domain {
  id: string;
  name: string;
  // Add other properties as needed based on your API response
}

export const useDomains = (token: string) => {
  const [domains, setDomains] = useState<Domain[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDomains = async () => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch('/api/domains', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch domains');
        }

        const data = await response.json();
        setDomains(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchDomains();
  }, [token]);

  return { domains, loading, error };
};
```

### Notes:
- This hook assumes your Next.js app has an API route at `/api/domains` that handles the `GET /domains` request.
- You can adjust the `Domain` interface based on your actual API response.
- If you're using Next.js App Router, ensure that your API route is correctly set up.
